      "ja": "動詞・形容詞は子音末に-으며、母音・ㄹ末に-며、名詞は(이)며。읽으며・가며・살며・학생이며。性質の列挙や動作の同時性を表し、文章でよく使います。",
      "en": "Verbs/adjectives take -으며 after consonants and -며 after vowels or ㄹ; nouns take (이)며: 읽으며, 가며, 살며, 학생이며. It lists properties or coordinates simultaneous actions, especially in prose.",
      "zh": "动词、形容词辅音后接-으며，元音或ㄹ后接-며；名词接(이)며，如읽으며、가며、살며、학생이며。常用于书面语列举性质或同时动作。"
