      "ja": "動詞は-는 것은 아니다、形容詞は-(으)ㄴ 것은 아니다、名詞は인 것은 아니다。完了動詞も-(으)ㄴ 것은 아니다です。모두・항상・반드시と使うと通常は全面的判断を否定します。",
      "en": "Use -는 것은 아니다 with present verbs, -(으)ㄴ 것은 아니다 with adjectives/completed verbs, and 인 것은 아니다 with nouns. With 모두, 항상, or 반드시, it typically rejects a universal claim.",
